function renderSimulator(){const ms=state.group.members;const bots=ms.filter(m=>m.kind==='bot');let currentBot=bots.find(m=>m.id===state.selectedBot)||bots[0];if(currentBot&&!state.selectedBot)state.selectedBot=currentBot.id;let lvl=riskFromForecast({gust:state.userWind,rain:state.userRain});const adminDisabled=!isAdmin()&&state.online;return `${title({eyebrow:'WEATHER LAB',heading:t('simulationLab'),desc:t('simulationSubtitle')})}<div class="status-banner">${sv('alert')}<strong>${eh(t('testWarning'))}</strong><span style="margin-left:auto;font-size:11px">TEST ENVIRONMENT</span></div><div class="mode-tabs" role="tablist" aria-label="${eh(t('chooseMode'))}"><button class="simtab" data-mode="user" aria-selected="${state.simMode==='user'}">${sv('users')}${eh(t('userMode'))}</button><button class="simtab" data-mode="admin" aria-selected="${state.simMode==='admin'}">${sv('settings')}${eh(t('adminMode'))}</button></div>
${state.simMode==='user'?`<div class="columns"><div class="sim-panel"><div class="sim-intro"><div class="sim-intro-icon">${sv('wind')}</div><div><h2>${eh(t('userModeTitle'))}</h2><p style="color:var(--sub);font-size:12px;line-height:1.7;margin:4px 0">${eh(t('userModeDesc'))}</p></div></div><div class="field" style="margin-bottom:16px"><label for="sim-user-city">${eh(t('city'))}</label><select id="sim-user-city">${cityOptions(state.userCity)}</select></div><div class="range-box"><div class="range-title"><label for="sim-wind">${eh(t('windGust'))}</label><output id="out-wind">${state.userWind} km/h</output></div><input id="sim-wind" type="range" min="0" max="140" step="5" value="${state.userWind}" /></div><div class="range-box" style="margin-top:13px"><div class="range-title"><label for="sim-rain">${eh(t('rainHour'))}</label><output id="out-rain">${state.userRain} mm</output></div><input id="sim-rain" type="range" min="0" max="55" step="1" value="${state.userRain}" /></div><div class="form-actions"><button class="btn primary" data-action="test-user">${sv('bell')}${eh(t('sendTestToGroup'))}</button></div></div><div class="card card-inner"><div class="card-header"><h3 class="card-title">${eh(t('preview'))}</h3><span class="tag sim">TEST</span></div><div id="user-preview"><div style="margin:15px 0">${formatRisk(lvl)}</div><h3 style="font-size:17px">${eh(t('inAppAlert'))}</h3><p class="text-muted" style="line-height:1.8;font-size:12px">${eh(t('hazardMsg').replace('{city}',locLabel(state.userCity)).replace('{name}',me()?.name||'').replace('{level}',riskLabel(lvl).toLowerCase()))}</p></div><hr class="divider"><div class="notice warn">${eh(t('sendGroupHelp'))}</div></div></div>`:
`<div class="columns"><div class="sim-panel"><div class="sim-intro"><div class="sim-intro-icon">${sv('bot')}</div><div><h2>${eh(t('adminModeTitle'))}</h2><p style="color:var(--sub);font-size:12px;line-height:1.7;margin:4px 0">${eh(t('adminModeDesc'))}</p></div></div>${adminDisabled?`<div class="notice error">${eh(t('notAdmin'))}</div>`:''}<div class="field"><label for="select-bot">${eh(t('chooseBot'))}</label><select id="select-bot" ${adminDisabled?'disabled':''}>${bots.map(b=>`<option value="${eh(b.id)}" ${currentBot?.id===b.id?'selected':''}>${eh(b.name)}</option>`).join('')}</select></div>${currentBot?`<div id="bot-form" class="bot-editor"><h3>${eh(t('bot'))} · ${eh(currentBot.name)}</h3><div class="form-grid"><div class="field"><label for="bot-name">${eh(t('botName'))}</label><input id="bot-name" maxlength="36" value="${eh(currentBot.name)}" ${adminDisabled?'disabled':''}/></div><div class="field"><label for="bot-city">${eh(t('botCity'))}</label><select id="bot-city" ${adminDisabled?'disabled':''}>${cityOptions(currentBot.cityId)}</select></div><div class="field full"><label for="bot-level">${eh(t('severity'))}</label><select id="bot-level" ${adminDisabled?'disabled':''}>${SEVERITIES.map(s=>`<option value="${s}" ${currentBot.sim===s?'selected':''}>${eh(riskLabel(s))}</option>`).join('')}</select></div></div><div class="form-actions"><button class="btn secondary" data-action="save-bot" ${adminDisabled?'disabled':''}>${sv('check')}${eh(t('saveBot'))}</button><button class="btn primary" data-action="broadcast-bot" ${adminDisabled?'disabled':''}>${sv('bell')}${eh(t('broadcastBot'))}</button></div></div>`:`<div class="blank" style="margin-top:16px">${sv('bot')}<strong>${eh(t('noBot'))}</strong></div>`}<div style="margin-top:17px"><button class="btn secondary" data-action="add-bot" ${adminDisabled?'disabled':''}>${sv('plus')}${eh(t('addBot'))}</button></div></div><div class="card card-inner"><div class="card-header"><h3 class="card-title">${eh(t('members'))}</h3><span class="tag sim">TEST</span></div>${bots.length?bots.map(b=>personRow(b)).join(''):`<div class="blank">${eh(t('noBot'))}</div>`}<hr class="divider"><div class="notice warn">${eh(t('testWarning'))}<div style="margin-top:7px">${eh(t('sendGroupHelp'))}</div></div></div></div>`}`}
function renderAlerts(){const arr=state.group.alerts||[];return `${title({eyebrow:'FAMILY NOTIFICATIONS',heading:t('notifications'),desc:t('alertsSubtitle'),action:`<button class="btn secondary" data-action="read-all">${sv('check')}${eh(t('readAll'))}</button>`})}${simulationBanner()}<div class="columns"><div class="card card-inner"><div class="card-header"><h3 class="card-title">${eh(t('recentAlerts'))}</h3><span class="tag sim">TEST / FORECAST</span></div>${arr.length?arr.map(activityItem).join(''):`<div class="blank">${sv('bell')}<strong>${eh(t('noAlerts'))}</strong><span>${eh(t('noAlertsHint'))}</span></div>`}</div><div class="card card-inner"><div class="card-header"><h3 class="card-title">${eh(t('notificationPermission'))}</h3>${sv('bell')}</div><p class="text-muted" style="font-size:12px;line-height:1.8">${eh(t('notifPermissionHelp'))}</p><button class="btn primary" data-action="notification-permission">${sv('bell')}${eh(t('enable'))}</button><hr class="divider"><div class="notice warn">${eh(t('testWarning'))}<br>${eh(t('noRealPush'))}</div></div></div>`}
function renderSettings(){return `${title({eyebrow:'PREFERENCES',heading:t('settings'),desc:t('settingsSubtitle')})}<div class="columns"><div class="card card-inner"><div class="card-header"><h3 class="card-title">${eh(t('language'))} & ${eh(t('modeInfo'))}</h3>${sv('settings')}</div><div class="field"><label for="settings-lang">${eh(t('language'))}</label><select id="settings-lang"><option value="vi" ${state.lang==='vi'?'selected':''}>Tiếng Việt</option><option value="en" ${state.lang==='en'?'selected':''}>English</option></select></div><div class="palette-setting"><strong>${eh(t('palette'))}</strong><p>${eh(t('paletteHint'))}</p><div class="palette-options"><label class="palette-choice"><input type="radio" name="theme-palette" value="mono" ${state.theme==='mono'?'checked':''}/><span class="palette-swatches"><i style="background:#fff"></i><i style="background:#151515"></i></span><span>${eh(t('whiteBlack'))}</span></label><label class="palette-choice"><input type="radio" name="theme-palette" value="navy" ${state.theme==='navy'?'checked':''}/><span class="palette-swatches"><i style="background:#fff"></i><i style="background:#183357"></i></span><span>${eh(t('whiteNavy'))}</span></label></div></div><div class="toggle-line"><div><strong>${eh(t('largeText'))}</strong><small>${eh(t('largeTextDesc'))}</small></div><input id="large-text-toggle" type="checkbox" ${state.largeText?'checked':''} aria-label="${eh(t('largeText'))}" /></div><hr class="divider"><div class="inline-group"><span class="tag ${state.online?'clear':'watch'}">${eh(t(state.online?'liveGroup':'localDemo'))}</span><span class="tiny text-muted">${eh(state.group?.name||t('noMember'))}</span></div><div class="form-actions"><button class="btn secondary small" data-action="export-demo">${sv('copy')}${eh(t('exportDemo'))}</button>${!state.online?`<button class="btn danger small" data-action="reset-demo">${eh(t('resetDemo'))}</button>`:''}</div><div class="form-actions"><button class="small-link" data-action="recheck">${eh(t('checkAgain'))}</button></div></div><div class="card card-inner"><div class="card-header"><h3 class="card-title">${eh(t('privacy'))}</h3>${sv('shield')}</div><ul class="list-simple">${[1,2,3,4].map(n=>`<li>${eh(t('privacy'+n))}</li>`).join('')}</ul><hr class="divider"><p class="text-muted" style="font-size:11px;line-height:1.8">${eh(t('stormDisclaimer'))}</p></div></div>`}
function modal(content){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Family Weather"><div class="modal-title"><h2>${eh(content.title||'Family Weather')}</h2><button class="close" data-close aria-label="Close">×</button></div>${content.body}</section></div>`;$('#modal-root [data-close]').onclick=closeModal;$('#modal-root .modal-backdrop').onclick=(e)=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};document.addEventListener('keydown',escModal,{once:true});setTimeout(()=>$('#modal-root input, #modal-root button')?.focus(),20)}
function escModal(e){if(e.key==='Escape')closeModal()};function closeModal(){$('#modal-root').replaceChildren()}
function confirmModal(title,body,yes){modal({title,body:`<p>${eh(body)}</p><div class="form-actions"><button class="btn danger" id="confirm-yes">${eh(t('confirm'))}</button><button class="btn secondary" data-close>${eh(t('cancel'))}</button></div>`});$('#confirm-yes').onclick=async()=>{closeModal();await yes()};}
function showInvite(code){modal({title:t('inviteTitle'),body:`<p>${eh(t('inviteHelp'))}</p><div class="code-display"><code>${eh(code)}</code><button class="btn secondary small" id="copy-code">${sv('copy')}${eh(t('copy'))}</button></div><p>${eh(t('codeHelp'))}</p>`});$('#copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(code);notify(t('copied'))}catch{notify(code)}}}
async function handleInvite(){try{let code;if(state.online){let d=await req('action','POST',{groupId:state.groupId,action:'invite'});code=d.code;}else{code='FW-'+Math.random().toString(36).slice(2,10).toUpperCase();state.group.invite={code,used:false,expiresAt:new Date(Date.now()+3*86400000).toISOString()};saveLocal()}showInvite(code)}catch(e){notify(e.message,'danger')}}
async function reloadGroup(showAlerts=true){if(!state.online||!state.groupId)return;const old=state.group;const d=await req('dashboard?groupId='+encodeURIComponent(state.groupId));state.group=d.group;if(showAlerts)checkNewAlerts(old,state.group);else state.initialAlertsReady=false;if(!state.group?.members?.find(m=>m.id===state.meId)){state.group=null;saveSession(null)}if(state.page==='map')updateChrome();else render()}
function checkNewAlerts(oldGroup,group){if(!group)return;const seen=new Set((oldGroup?.alerts||[]).map(a=>a.id));const incoming=(group.alerts||[]).filter(a=>!seen.has(a.id));if(!oldGroup || !state.initialAlertsReady){state.initialAlertsReady=true;return}for(const a of incoming){notify(`${a.simulation?'TEST':'Open-Meteo'} · ${a.memberName} · ${riskLabel(a.level)}`,a.level==='severe'?'danger':'success');notifyBrowser(a);}}
function notifyBrowser(a){if(typeof Notification==='undefined'||Notification.permission!=='granted')return;try{new Notification((a.simulation?'TEST':'Forecast')+' · Family Weather',{body:t(a.simulation?'hazardMsg':'forecastHazardMsg').replace('{city}',locLabel(a.cityId)).replace('{name}',a.memberName).replace('{level}',riskLabel(a.level)),tag:a.id})}catch{}}
async function groupAction(action,payload={}){if(state.online){const d=await req('action','POST',{groupId:state.groupId,action,...payload});if(action!=='leave'&&action!=='delete-group')await reloadGroup(false);return d;}const g=state.group;if(!g)throw Error(t('error'));if(action==='add-bot'){if(!isAdmin())throw Error(t('notAdmin'));if(g.members.length>=15)throw Error('Maximum 15 members');const b={id:uid(),name:payload.name,role:'member',kind:'bot',cityId:payload.cityId,sim:'clear',joinedAt:new Date().toISOString()};g.members.push(b);state.selectedBot=b.id;}
else if(action==='edit-bot'){const b=g.members.find(m=>m.id===payload.botId&&m.kind==='bot');if(!b)throw Error('Bot unavailable');b.name=payload.name;b.cityId=payload.cityId;b.sim=payload.level;}
else if(action==='test-alert'){const m=g.members.find(m=>m.id===(payload.memberId||state.meId));if(!m)throw Error('Member unavailable');let a=newAlert({member:m,level:payload.level,actor:payload.actor||'user',cityId:payload.cityId||m.cityId,wind:payload.wind,rain:payload.rain});g.alerts.unshift(a);g.alerts=g.alerts.slice(0,60);notifyBrowser(a);}
else if(action==='set-city'){const m=g.members.find(m=>m.id===state.meId);m.cityId=payload.cityId;m.gps=null;}
else if(action==='set-gps'){const m=g.members.find(m=>m.id===state.meId);m.gps={lat:payload.lat,lon:payload.lon,updatedAt:new Date().toISOString()};}
else if(action==='remove-member'){g.members=g.members.filter(m=>m.id!==payload.memberId)}
else if(action==='leave'){state.group=null;localStorage.removeItem(DEMO_KEY);go('map');return{ok:true}}
else if(action==='delete-group'){state.group=null;localStorage.removeItem(DEMO_KEY);go('map');return{ok:true}}
saveLocal();render();return{ok:true};}
function addBotModal(){if(!isAdmin())return notify(t('notAdmin'),'danger');modal({title:t('addBot'),body:`<div class="field"><label for="new-bot-name">${eh(t('botName'))}</label><input id="new-bot-name" maxlength="36" value="Bot ${state.group.members.filter(m=>m.kind==='bot').length+1}" /></div><div class="field"><label for="new-bot-city">${eh(t('botCity'))}</label><select id="new-bot-city">${cityOptions('dn')}</select></div><p>${eh(t('createBotHint'))}</p><button id="add-bot-submit" class="btn primary">${sv('plus')}${eh(t('addBot'))}</button>`});$('#add-bot-submit').onclick=async()=>{const name=$('#new-bot-name').value.trim(),cityId=$('#new-bot-city').value;if(!validName(name))return notify(t('needName'),'danger');try{await groupAction('add-bot',{name,cityId});closeModal();notify(t('botAdded'));go('simulator');state.simMode='admin';render();}catch(e){notify(e.message,'danger')}}}
function attachActions(){ $$('[data-action]').forEach(b=>b.addEventListener('click',async()=>{const a=b.dataset.action;try{if(a==='invite')return handleInvite();if(a==='go-simulator')return go('simulator');if(a==='go-family')return go('family');if(a==='go-alerts')return go('alerts');if(a==='add-bot')return addBotModal();if(a==='refresh')return refreshWeather(true);if(a==='gps')return requestGPS();if(a==='read-all'){const seen=JSON.parse(localStorage.getItem(storePrefs('seen'))||'{}');(state.group.alerts||[]).forEach(a=>seen[a.id]=true);localStorage.setItem(storePrefs('seen'),JSON.stringify(seen));return render()}
if(a==='notification-permission'){if(typeof Notification==='undefined')throw Error(t('permissionBlocked'));const d=await Notification.requestPermission();notify(d==='granted'?t('permissionDone'):t('permissionBlocked'),d==='granted'?'success':'danger');return;}
if(a==='reset-demo')return confirmModal(t('resetDemo'),t('resetConfirm'),async()=>{localStorage.removeItem(DEMO_KEY);state.group=null;state.meId='me';go('dashboard')});
if(a==='export-demo'){let data=JSON.stringify({exportedAt:new Date().toISOString(),group:state.group},null,2);const blob=new Blob([data],{type:'application/json'});const url=URL.createObjectURL(blob);const aa=document.createElement('a');aa.href=url;aa.download='family-weather-export.json';aa.click();setTimeout(()=>URL.revokeObjectURL(url),250);return}
if(a==='recheck'){const online=await checkBackend();notify(online?t('apiReady'):t('apiUnavailable'),online?'success':'danger');return}
if(a==='remove-member'){const member=state.group.members.find(m=>m.id===b.dataset.id);if(!member)return;return confirmModal(t('kick'),t('confirmRemove'),async()=>{try{await groupAction('remove-member',{memberId:member.id});notify(t('saved'));}catch(e){notify(e.message,'danger')}})}
if(a==='leave')return confirmModal(t('leave'),t('confirmLeave'),async()=>{await groupAction('leave');if(state.online)saveSession(null);state.group=null;render()});
if(a==='delete-group')return confirmModal(t('deleteGroup'),t('confirmDelete'),async()=>{await groupAction('delete-group');if(state.online)saveSession(null);state.group=null;render()});
if(a==='save-bot'){const currentBot=state.group.members.find(m=>m.id===state.selectedBot);if(!currentBot)return;let name=$('#bot-name').value.trim(),cityId=$('#bot-city').value,level=$('#bot-level').value;if(!validName(name))throw Error(t('needName'));await groupAction('edit-bot',{botId:currentBot.id,name,cityId,level});notify(t('botUpdated'));return;}
if(a==='broadcast-bot'){const currentBot=state.group.members.find(m=>m.id===state.selectedBot);if(!currentBot)return;const name=$('#bot-name').value.trim(),cityId=$('#bot-city').value,level=$('#bot-level').value;if(!validName(name))throw Error(t('needName'));await groupAction('edit-bot',{botId:currentBot.id,name,cityId,level});await groupAction('test-alert',{memberId:currentBot.id,cityId,level,actor:'admin'});notify(t('testSent'));return;}
if(a==='test-user'){let level=riskFromForecast({gust:state.userWind,rain:state.userRain});await groupAction('test-alert',{memberId:state.meId,cityId:state.userCity,level,wind:state.userWind,rain:state.userRain,actor:'user'});notify(t('testSent'));return;}
}catch(err){notify(err.message||t('error'),'danger')}}))}
function bindView(){attachActions();$('#location-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await groupAction('set-city',{cityId:$('#my-city').value});notify(t('locationSaved'));refreshWeather();}catch(err){notify(err.message,'danger')}});$('#settings-lang')?.addEventListener('change',e=>{state.lang=e.target.value;localStorage.setItem(storePrefs('language'),state.lang);render()});$$('[name=theme-palette]').forEach(r=>r.addEventListener('change',e=>{if(!e.target.checked)return;state.theme=e.target.value;localStorage.setItem(storePrefs('theme'),state.theme);render()}));$('#large-text-toggle')?.addEventListener('change',e=>{state.largeText=e.target.checked;localStorage.setItem(storePrefs('large_text'),state.largeText?'1':'0');render()});$$('.simtab').forEach(b=>b.onclick=()=>{state.simMode=b.dataset.mode;render()});$('#select-bot')?.addEventListener('change',e=>{state.selectedBot=e.target.value;render()});$('#sim-user-city')?.addEventListener('change',e=>{state.userCity=e.target.value;render()});$('#sim-wind')?.addEventListener('input',e=>{state.userWind=+e.target.value;updateSimPreview()});$('#sim-rain')?.addEventListener('input',e=>{state.userRain=+e.target.value;updateSimPreview()});}
function updateSimPreview(){const lvl=riskFromForecast({gust:state.userWind,rain:state.userRain});$('#out-wind').textContent=state.userWind+' km/h';$('#out-rain').textContent=state.userRain+' mm';$('#user-preview').innerHTML=`<div style="margin:15px 0">${formatRisk(lvl)}</div><h3 style="font-size:17px">${eh(t('inAppAlert'))}</h3><p class="text-muted" style="line-height:1.8;font-size:12px">${eh(t('hazardMsg').replace('{city}',locLabel(state.userCity)).replace('{name}',me()?.name||'').replace('{level}',riskLabel(lvl).toLowerCase()))}</p>`;}
function requestGPS(){if(!navigator.geolocation)return notify(t('gpsDenied'),'danger');navigator.geolocation.getCurrentPosition(async p=>{try{await groupAction('set-gps',{lat:+p.coords.latitude,lon:+p.coords.longitude});notify(t('gpsSuccess'));refreshWeather(true)}catch(e){notify(e.message,'danger')}},()=>notify(t('gpsDenied'),'danger'),{enableHighAccuracy:false,timeout:15000,maximumAge:5*60*1000})}
async function refreshWeather(force=false){if(!state.group||state.fetching)return;state.fetching=true;let ids=[...new Set(state.group.members.map(m=>m.cityId))].filter(Boolean).slice(0,12);try{await Promise.all(ids.map(async id=>{if(!force&&state.forecast[id]&&dateAge(state.forecast[id].at)<20*60*1000)return;let c=CITY_BY_ID[id];if(!c)return;const u=new URL('https://api.open-meteo.com/v1/forecast');u.searchParams.set('latitude',c.lat);u.searchParams.set('longitude',c.lon);u.searchParams.set('current','temperature_2m,weather_code,wind_speed_10m');u.searchParams.set('hourly','wind_gusts_10m,precipitation,weather_code');u.searchParams.set('forecast_hours','12');u.searchParams.set('wind_speed_unit','kmh');u.searchParams.set('timezone','Asia/Ho_Chi_Minh');const response=await fetch(u);if(!response.ok)throw Error('Open-Meteo unavailable');const d=await response.json();const gust=Math.max(...(d.hourly?.wind_gusts_10m||[]).filter(Number.isFinite),0),rain=Math.max(...(d.hourly?.precipitation||[]).filter(Number.isFinite),0);state.forecast[id]={temp:d.current?.temperature_2m??null,gust,rain,risk:riskFromForecast({gust,rain}),at:new Date().toISOString()}}));state.weatherError='';}catch(e){state.weatherError=e.message;}finally{state.fetching=false;if(state.page==='dashboard'||state.page==='family')render();else updateFloatingGroup();}}
init();
